<?php
 namespace App\Http\Middleware; use Illuminate\Support\Facades\Cache; use Closure; use Illuminate\Http\Request; use App\Services\LicenseService; class ValidateLicense { protected $licenseService; public function __construct(LicenseService $licenseService) { $this->licenseService = $licenseService; } public function handle(Request $request, Closure $next) { dd([ 'Status Middleware' => 'AKTIF (Jalan)', 'Cek Kunci Cache' => Cache::has('app_offline_lock') ? 'ADA (Terkunci)' : 'TIDAK ADA (Aman)', 'Nama Kunci' => 'app_offline_lock' ]); if (Cache::has('app_offline_lock')) { if (!$request->routeIs('license.activate.*')) { return redirect()->route('license.activate.form') ->with('error', 'Validasi Mingguan Gagal (Offline). Mohon konek internet sebentar.'); } } $license = $this->licenseService->loadLocalLicense(); $isActive = $license && ($license['status'] ?? 'blocked') === 'active'; if (!$isActive) { $payload = [ 'valid' => false, 'message' => $license['message'] ?? 'Lisensi tidak valid atau diblokir.', 'status' => $license['status'] ?? 'blocked', ]; if ($request->expectsJson()) { return response()->json($payload, 403); } return redirect()->route('license.activate.form') ->with('error', $payload['message']) ->with('status', $payload['status']); } return $next($request); } } 